# frozen_string_literal: true

# Regenerates showcase/coverage_data.rb from a full, eager build of every page.
#
#   ruby -I../zui/lib script/generate_coverage.rb

ENV["ZUI_SHOWCASE_EAGER"] = "1"
require_relative "../app"

types = Showcase.rendered_types(Showcase.build.tree)
raise "eager build produced no components" if types.empty?

target = File.expand_path("../showcase/coverage_data.rb", __dir__)
body = types.each_slice(4).map { |slice| slice.map(&:inspect).join(", ") }.join(",\n")
File.write(target, <<~RUBY)
  # frozen_string_literal: true

  # Generated by script/generate_coverage.rb — do not edit by hand.
  #
  # Every component type the showcase really instantiates, collected by building
  # all sixteen pages in one pass. The running application renders one page at a
  # time, so it cannot count this itself; script/verify.rb rebuilds everything and
  # fails if this list has drifted.
  module Showcase
    COVERAGE_TYPES = [
      #{body.gsub("\n", "\n    ")}
    ].freeze
  end
RUBY

puts "wrote #{types.size} component types to showcase/coverage_data.rb"
